function validate([path]) {
  if (typeof path !== 'string' || path.length < 1 || path.length > 10000) return 'path has 1 to 10^4 letters.';
  if (!/^[NSEW]+$/.test(path)) return "path uses only the letters 'N', 'S', 'E' and 'W'.";
  return null;
}

