function isPathCrossing(path) {
  const seen = new Set(['0,0']);
  let x = 0;
  let y = 0;
  for (const step of path) {
    if (step === 'N') y++;
    else if (step === 'S') y--;
    else if (step === 'E') x++;
    else x--;
    const key = x + ',' + y;
    if (seen.has(key)) {
      return true;
    }
    seen.add(key);
  }
  return false;
}

