function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const all = 'NSEW';
  const n = size === 'large' ? int(9000, 10000) : int(1, 10);
  const roll = rand();
  if (roll < 0.4) {
    // Only two perpendicular directions: the path never revisits a point.
    const pair = [['N', 'E'], ['N', 'W'], ['S', 'E'], ['S', 'W']][int(0, 3)];
    let path = Array.from({ length: n }, () => pair[int(0, 1)]).join('');
    // Sometimes the last move undoes the one before it, so the only crossing is at the very end.
    if (n >= 2 && rand() < 0.5) {
      const back = { N: 'S', S: 'N', E: 'W', W: 'E' }[path[n - 2]];
      path = path.slice(0, n - 1) + back;
    }
    return [path];
  }
  return [Array.from({ length: n }, () => all[int(0, 3)]).join('')];
}
